import React, { useState } from "react";
import { ShoppingCart, PlusCircle, BarChart2, LogOut } from "lucide-react";

export default function FarmerDashboard() {
  const [products, setProducts] = useState([
    { id: 1, name: "Tomato", price: 30, stock: 50 },
    { id: 2, name: "Potato", price: 25, stock: 40 },
  ]);

  const [name, setName] = useState("");
  const [price, setPrice] = useState("");
  const [stock, setStock] = useState("");

  const addProduct = (e) => {
    e.preventDefault();

    if (!name || !price || !stock) {
      alert("Please fill all fields");
      return;
    }

    const newProduct = {
      id: Date.now(),
      name,
      price,
      stock,
    };

    setProducts([...products, newProduct]);
    setName("");
    setPrice("");
    setStock("");
  };

  const deleteProduct = (id) => {
    setProducts(products.filter((p) => p.id !== id));
  };

  return (
    <div className="min-h-screen bg-gray-100 p-6">
      {/* Header */}
      <div className="flex justify-between items-center bg-white p-5 rounded-2xl shadow mb-6">
        <h2 className="text-2xl font-bold text-green-700">Farmer Dashboard</h2>
        <button className="flex items-center gap-2 text-red-500 hover:text-red-600">
          <LogOut size={20} /> Logout
        </button>
      </div>

      {/* Stats */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-5 mb-6">
        <div className="bg-white p-5 rounded-2xl shadow flex items-center gap-4">
          <ShoppingCart className="text-green-600" />
          <div>
            <h3 className="text-lg font-semibold">Total Products</h3>
            <p className="text-gray-600">{products.length}</p>
          </div>
        </div>

        <div className="bg-white p-5 rounded-2xl shadow flex items-center gap-4">
          <BarChart2 className="text-blue-600" />
          <div>
            <h3 className="text-lg font-semibold">Total Stock</h3>
            <p className="text-gray-600">
              {products.reduce((sum, p) => sum + Number(p.stock), 0)}
            </p>
          </div>
        </div>

        <div className="bg-white p-5 rounded-2xl shadow flex items-center gap-4">
          <PlusCircle className="text-purple-600" />
          <div>
            <h3 className="text-lg font-semibold">Add Products</h3>
            <p className="text-gray-600">Manage Inventory</p>
          </div>
        </div>
      </div>

      {/* Add Product Form */}
      <div className="bg-white p-6 rounded-2xl shadow mb-6">
        <h3 className="text-xl font-semibold mb-4">Add New Product</h3>

        <form
          onSubmit={addProduct}
          className="grid grid-cols-1 md:grid-cols-3 gap-4"
        >
          <input
            type="text"
            placeholder="Product Name"
            value={name}
            onChange={(e) => setName(e.target.value)}
            className="border rounded-xl px-4 py-2 focus:ring-2 focus:ring-green-400 outline-none"
          />

          <input
            type="number"
            placeholder="Price (₹)"
            value={price}
            onChange={(e) => setPrice(e.target.value)}
            className="border rounded-xl px-4 py-2 focus:ring-2 focus:ring-green-400 outline-none"
          />

          <input
            type="number"
            placeholder="Stock"
            value={stock}
            onChange={(e) => setStock(e.target.value)}
            className="border rounded-xl px-4 py-2 focus:ring-2 focus:ring-green-400 outline-none"
          />

          <button
            type="submit"
            className="md:col-span-3 bg-green-600 text-white py-2 rounded-xl hover:bg-green-700 transition"
          >
            Add Product
          </button>
        </form>
      </div>

      {/* Product Table */}
      <div className="bg-white p-6 rounded-2xl shadow">
        <h3 className="text-xl font-semibold mb-4">My Products</h3>

        <div className="overflow-x-auto">
          <table className="w-full border-collapse">
            <thead>
              <tr className="bg-gray-100">
                <th className="p-3 text-left">Name</th>
                <th className="p-3 text-left">Price (₹)</th>
                <th className="p-3 text-left">Stock</th>
                <th className="p-3 text-left">Action</th>
              </tr>
            </thead>

            <tbody>
              {products.map((p) => (
                <tr key={p.id} className="border-b">
                  <td className="p-3">{p.name}</td>
                  <td className="p-3">{p.price}</td>
                  <td className="p-3">{p.stock}</td>
                  <td className="p-3">
                    <button
                      onClick={() => deleteProduct(p.id)}
                      className="text-red-500 hover:underline"
                    >
                      Delete
                    </button>
                  </td>
                </tr>
              ))}

              {products.length === 0 && (
                <tr>
                  <td colSpan="4" className="p-4 text-center text-gray-500">
                    No products added yet
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
}
